  1102  CAPSTONE_EXPORT
  1103  bool CAPSTONE_API cs_disasm_iter(csh ud, const uint8_t **code, size_t *size,
  1104                  uint64_t *address, cs_insn *insn)
  1105  {
  1106          struct cs_struct *handle;
  1107          uint16_t insn_size;
  1108          MCInst mci;
  1109          bool r;
  1110
  1111          handle = (struct cs_struct *)(uintptr_t)ud;
  1112          if (!handle) {
  1113                  return false;
  1114          }
  1115
  1116          handle->errnum = CS_ERR_OK;
  1117
  1118          MCInst_Init(&mci);
  1119          mci.csh = handle;
  1120
  1121          // relative branches need to know the address & size of current insn
  1122          mci.address = *address;
  1123
  1124          // save all the information for non-detailed mode
  1125          mci.flat_insn = insn;
  1126          mci.flat_insn->address = *address;
  1127  #ifdef CAPSTONE_DIET
  1128          // zero out mnemonic & op_str
  1129          mci.flat_insn->mnemonic[0] = '\0';
  1130          mci.flat_insn->op_str[0] = '\0';
  1131  #endif
  1132
  1133          r = handle->disasm(ud, *code, *size, &mci, &insn_size, *address, handle->getinsn_info);
  1134          if (r) {
  1135                  SStream ss;
  1136                  SStream_Init(&ss);
  1137
  1138                  mci.flat_insn->size = insn_size;
  1139
  1140                  // map internal instruction opcode to public insn ID
  1141                  handle->insn_id(handle, insn, mci.Opcode);
  1142
  1143                  handle->printer(&mci, &ss, handle->printer_info);
  1144
  1145                  fill_insn(handle, insn, ss.buffer, &mci, handle->post_printer, *code);
  1146
