  1151                  *code += insn_size;
  1152                  *size -= insn_size;
  1153                  *address += insn_size;
  1154          } else {        // encounter a broken instruction
  1155                  size_t skipdata_bytes;
  1156
  1157                  // if there is no request to skip data, or remaining data is too small,
  1158                  // then bail out
  1159                  if (!handle->skipdata || handle->skipdata_size > *size)
  1160                          return false;
  1161
  1162                  if (handle->skipdata_setup.callback) {
  1163                          skipdata_bytes = handle->skipdata_setup.callback(*code, *size,
  1164                                          0, handle->skipdata_setup.user_data);
  1165                          if (skipdata_bytes > *size)
  1166                                  // remaining data is not enough
  1167                                  return false;
  1168
  1169                          if (!skipdata_bytes)
  1170                                  // user requested not to skip data, so bail out
  1171                                  return false;
  1172                  } else
  1173                          skipdata_bytes = handle->skipdata_size;
  1174
  1175                  // we have to skip some amount of data, depending on arch & mode
  1176                  insn->id = 0;   // invalid ID for this "data" instruction
  1177                  insn->address = *address;
  1178                  insn->size = (uint16_t)skipdata_bytes;
  1179  #ifdef CAPSTONE_DIET
  1180                  insn->mnemonic[0] = '\0';
  1181                  insn->op_str[0] = '\0';
  1182  #else
  1183                  memcpy(insn->bytes, *code, skipdata_bytes);
  1184                  strncpy(insn->mnemonic, handle->skipdata_setup.mnemonic,
  1185                                  sizeof(insn->mnemonic) - 1);
  1186                  skipdata_opstr(insn->op_str, *code, skipdata_bytes);
  1187  #endif
  1188
  1189                  *code += skipdata_bytes;
